package io.github.describeadmin.codegen;

import static org.junit.jupiter.api.Assertions.assertEquals;

import java.lang.reflect.Method;
import java.net.URI;
import java.nio.file.FileSystem;
import java.nio.file.FileSystems;
import java.nio.file.Path;
import java.util.Map;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class CodegenCliMutaGate3Test {

    @TempDir
    Path tempDir;

    @Test
    void displayFallsBackToTargetStringWhenRelativizeThrows() throws Exception {
        Path zip = tempDir.resolve("t.zip");
        URI uri = URI.create("jar:" + zip.toUri());

        try (FileSystem zipFs = FileSystems.newFileSystem(uri, Map.of("create", "true"))) {
            // Path from a different provider: relativize on the default-fs path
            // throws ProviderMismatchException (an IllegalArgumentException).
            Path target = zipFs.getPath("/a/b\\c.txt");
            Path outDir = tempDir.resolve("out");

            Method display = CodegenCli.class.getDeclaredMethod("display", Path.class, Path.class);
            display.setAccessible(true);
            String result = (String) display.invoke(null, outDir, target);

            assertEquals(target.toString().replace('\\', '/'), result);
            assertEquals("/a/b/c.txt", result);
        }
    }
}

package io.github.describeadmin.codegen;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.fail;

import java.io.File;
import java.security.Permission;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.TimeUnit;

import org.junit.jupiter.api.Test;

class CodegenCliMutaGate4Test {

    static final class ExitException extends SecurityException {
        final int status;

        ExitException(int status) {
            super("exit " + status);
            this.status = status;
        }
    }

    @SuppressWarnings("removal")
    static final class NoExitSecurityManager extends SecurityManager {
        final List<Integer> statuses = new ArrayList<>();

        @Override
        public void checkPermission(Permission perm) {
            // allow everything
        }

        @Override
        public void checkPermission(Permission perm, Object context) {
            // allow everything
        }

        @Override
        public void checkExit(int status) {
            statuses.add(status);
            throw new ExitException(status);
        }
    }

    @Test
    @SuppressWarnings("removal")
    void mainExitsWithStatusReturnedByRun() throws Exception {
        NoExitSecurityManager sm = new NoExitSecurityManager();
        SecurityManager original = System.getSecurityManager();
        boolean installed;
        try {
            System.setSecurityManager(sm);
            installed = true;
        } catch (UnsupportedOperationException e) {
            installed = false;
        }

        if (installed) {
            try {
                CodegenCli.main(new String[0]);
                fail("main should call System.exit");
            } catch (ExitException expected) {
                // expected
            } finally {
                System.setSecurityManager(original);
            }
            assertFalse(sm.statuses.isEmpty());
            // no args => run() returns 1 => first exit call must carry 1
            assertEquals(1, sm.statuses.get(0));
            return;
        }

        // Fallback: run main in a separate JVM and check its exit code
        String javaBin = System.getProperty("java.home") + File.separator + "bin" + File.separator + "java";
        ProcessBuilder pb = new ProcessBuilder(javaBin, "-cp", System.getProperty("java.class.path"),
                "io.github.describeadmin.codegen.CodegenCli");
        pb.redirectErrorStream(true);
        pb.redirectOutput(ProcessBuilder.Redirect.DISCARD);
        Process p = pb.start();
        if (!p.waitFor(60, TimeUnit.SECONDS)) {
            p.destroyForcibly();
            fail("child JVM timed out");
        }
        assertEquals(1, p.exitValue());
    }
}

package io.github.describeadmin.codegen;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.concurrent.TimeUnit;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class CodegenCliMutaGate5Test {

    @TempDir
    Path tmp;

    @Test
    void mainPrintsSpecErrorMessageAndExitsWithTwo() throws Exception {
        Path spec = tmp.resolve("bad.yaml");
        Files.writeString(spec, "unknownKey: value\n", StandardCharsets.UTF_8);

        String javaBin = Path.of(System.getProperty("java.home"), "bin", "java").toString();
        ProcessBuilder pb = new ProcessBuilder(
                javaBin,
                "-Dfile.encoding=UTF-8",
                "-cp", System.getProperty("java.class.path"),
                "io.github.describeadmin.codegen.CodegenCli",
                spec.toString());
        pb.redirectError(ProcessBuilder.Redirect.DISCARD);
        pb.environment().remove("CODEGEN_LAYOUT");

        Process p = pb.start();
        byte[] bytes = p.getInputStream().readAllBytes();
        assertTrue(p.waitFor(60, TimeUnit.SECONDS), "subprocess timed out");
        String stdout = new String(bytes, StandardCharsets.UTF_8);

        assertEquals(2, p.exitValue(), "stdout was: " + stdout);
        assertTrue(stdout.startsWith("✗ "), "stdout was: " + stdout);
        assertTrue(stdout.trim().length() > 2, "stdout was: " + stdout);
    }
}

package io.github.describeadmin.codegen;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.File;
import java.io.PrintStream;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.security.Permission;
import org.junit.jupiter.api.Test;

class CodegenCliMutaGate6Test {

    static final class ExitCalled extends SecurityException {
        final int status;

        ExitCalled(int status) {
            super("exit " + status);
            this.status = status;
        }
    }

    @SuppressWarnings("removal")
    static final class NoExitManager extends SecurityManager {
        @Override
        public void checkPermission(Permission perm) {
            // allow everything
        }

        @Override
        public void checkPermission(Permission perm, Object context) {
            // allow everything
        }

        @Override
        public void checkExit(int status) {
            throw new ExitCalled(status);
        }
    }

    @Test
    @SuppressWarnings("removal")
    void invalidSpecMakesMainExitWithCodeTwo() throws Exception {
        Path dir = Files.createTempDirectory("codegen-cli-test");
        Path spec = dir.resolve("bad.yaml");
        Files.writeString(spec, "foo: bar\n", StandardCharsets.UTF_8);

        SecurityManager previous = System.getSecurityManager();
        boolean installed = false;
        try {
            System.setSecurityManager(new NoExitManager());
            installed = true;
        } catch (UnsupportedOperationException e) {
            installed = false;
        }

        if (installed) {
            PrintStream originalOut = System.out;
            Integer exitStatus = null;
            try {
                System.setOut(new PrintStream(new java.io.ByteArrayOutputStream(), true, StandardCharsets.UTF_8));
                try {
                    CodegenCli.main(new String[] {spec.toString()});
                } catch (ExitCalled e) {
                    exitStatus = e.status;
                }
            } finally {
                System.setOut(originalOut);
                System.setSecurityManager(previous);
            }
            assertEquals(Integer.valueOf(2), exitStatus);
        } else {
            String javaBin = Path.of(System.getProperty("java.home"), "bin", "java").toString();
            ProcessBuilder pb = new ProcessBuilder(
                    javaBin,
                    "-cp", System.getProperty("java.class.path"),
                    "io.github.describeadmin.codegen.CodegenCli",
                    spec.toString());
            pb.redirectErrorStream(true);
            pb.redirectOutput(new File(dir.toFile(), "out.txt"));
            Process p = pb.start();
            int code = p.waitFor();
            assertTrue(Files.exists(dir.resolve("out.txt")));
            assertEquals(2, code);
        }
    }
}

