import java.security.Permission;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.TimeUnit;

import org.junit.jupiter.api.Test;

class CodegenCliMutaGate4Test {

    static final class ExitException extends SecurityException {
        final int status;

        ExitException(int status) {
            super("exit " + status);
            this.status = status;
        }
    }

    @SuppressWarnings("removal")
    static final class NoExitSecurityManager extends SecurityManager {
        final List<Integer> statuses = new ArrayList<>();

        @Override
        public void checkPermission(Permission perm) {
            // allow everything
        }

        @Override
        public void checkPermission(Permission perm, Object context) {
            // allow everything
        }

        @Override
        public void checkExit(int status) {
            statuses.add(status);
            throw new ExitException(status);
        }
    }

    @Test
    @SuppressWarnings("removal")
    void mainExitsWithStatusReturnedByRun() throws Exception {
        NoExitSecurityManager sm = new NoExitSecurityManager();
        SecurityManager original = System.getSecurityManager();
        boolean installed;
        try {
            System.setSecurityManager(sm);
            installed = true;
        } catch (UnsupportedOperationException e) {
            installed = false;
        }

        if (installed) {
            try {
                CodegenCli.main(new String[0]);
                fail("main should call System.exit");
            } catch (ExitException expected) {
                // expected
            } finally {
                System.setSecurityManager(original);
            }
            assertFalse(sm.statuses.isEmpty());
            // no args => run() returns 1 => first exit call must carry 1
            assertEquals(1, sm.statuses.get(0));
            return;
        }

        // Fallback: run main in a separate JVM and check its exit code
        String javaBin = System.getProperty("java.home") + File.separator + "bin" + File.separator + "java";
        ProcessBuilder pb = new ProcessBuilder(javaBin, "-cp", System.getProperty("java.class.path"),
                "io.github.describeadmin.codegen.CodegenCli");
        pb.redirectErrorStream(true);
        pb.redirectOutput(ProcessBuilder.Redirect.DISCARD);
        Process p = pb.start();
        if (!p.waitFor(60, TimeUnit.SECONDS)) {
            p.destroyForcibly();
            fail("child JVM timed out");
        }
        assertEquals(1, p.exitValue());
    }
}
