class CodegenCliMutaGate15Test {

    @Test
    void layoutOptionConsumesItsValueAndParsingContinues() throws Exception {
        ByteArrayOutputStream buf = new ByteArrayOutputStream();
        PrintStream out = new PrintStream(buf, true, StandardCharsets.UTF_8);
        AtomicReference<Integer> result = new AtomicReference<>();
        AtomicReference<Throwable> error = new AtomicReference<>();

        String[] args = {"definitely-missing-spec.yaml", "--layout", "flat", "--bogus"};

        Thread t = new Thread(() -> {
            try {
                result.set(CodegenCli.run(args, out));
            } catch (Throwable e) {
                error.set(e);
            }
        });
        t.setDaemon(true);
        t.start();
        t.join(5000);

        // If the index moved backwards, parsing would loop forever.
        assertFalse(t.isAlive(), "argument parsing must terminate");
        assertNull(error.get());
        assertEquals(1, result.get());

        String text = buf.toString(StandardCharsets.UTF_8);
        assertTrue(text.contains("未知参数: --bogus"), text);
        assertFalse(text.contains("未知参数: flat"), text);
    }
}
