        int n = 0;
        for (String pkgKey : new String[] {"basePackage", "package"}) {
            for (String type : new String[] {"string", "String"}) {
                Path p = tmp.resolve("cand" + (n++) + ".yaml");
                Files.writeString(p, yaml(pkgKey, type), StandardCharsets.UTF_8);
                list.add(p);
